"""Auto-generated full inheritance graph, rendered via native graphviz.

The {manim-inheritance} directive enumerates every public class of the
installed manim package at build time, derives the complete inheritance
edge set, and renders it as an inline SVG (see inheritance_graph below).
The {manimchain} directive renders a small hand-written DOT diagram (e.g.
a single class's inheritance chain) through the same path.

Node links resolve to documentation sections:

- classes covered by a tutorial chapter point at the chapter anchor
  (config ``manim_inheritance_links``: JSON with ``nodes[{name,link}]``,
  old ``/ch/<part>/<sec>#<anchor>`` routes are normalized);
- every other class points at its autodoc API reference entry
  (config ``manim_inheritance_api_map``: class name -> URL, generated by
  scripts/build_docs.py together with the api/ pages).

This module is also imported by scripts/build_docs.py: API_GROUPS and
group_api_page() are the single source of truth for the api/ page
grouping shared by both sides.
"""

from __future__ import annotations

import functools
import inspect
import json
import re
import subprocess
from pathlib import Path

from docutils import nodes
from docutils.parsers.rst import Directive
from sphinx.errors import SphinxError
from sphinx.util import logging

logger = logging.getLogger(__name__)

# --- API page grouping (shared with scripts/build_docs.py) -----------------
# First match wins; keep in sync with the api/ toctree order.
API_GROUPS: list[tuple[str, str, object]] = [
    ("animation", "动画（animation）", lambda m: m.startswith("manim.animation")),
    ("mobject", "Mobject 核心", lambda m: m == "manim.mobject" or (
        m.startswith("manim.mobject.") and m.split(".")[2] not in {
            "types", "geometry", "graphing", "svg", "text", "three_d", "opengl",
        })),
    ("types", "Mobject 基类类型（types）", lambda m: m.startswith("manim.mobject.types")),
    ("geometry", "几何图形（geometry）", lambda m: m.startswith("manim.mobject.geometry")),
    ("graphing", "图表与坐标（graphing）", lambda m: m.startswith("manim.mobject.graphing")),
    ("svg", "SVG 与位图（svg）", lambda m: m.startswith("manim.mobject.svg")),
    ("text", "文本与公式（text）", lambda m: m.startswith("manim.mobject.text")),
    ("three_d", "三维对象（three_d）", lambda m: m.startswith("manim.mobject.three_d")),
    ("opengl", "OpenGL 对象（opengl）", lambda m: m.startswith("manim.mobject.opengl")),
    ("camera", "摄像机（camera）", lambda m: m.startswith("manim.camera")),
    ("scene", "场景（scene）", lambda m: m.startswith("manim.scene")),
    ("utils", "工具（utils）", lambda m: m.startswith("manim.utils")),
    ("core", "核心与其他", lambda m: True),
]


def group_api_page(module: str) -> str:
    for gid, _title, pred in API_GROUPS:
        if pred(module):
            return gid
    return "core"


@functools.lru_cache(maxsize=1)
def load_manim_classes() -> dict[str, type]:
    """Every public manim class, keyed by its top-level name."""
    try:
        import manim
    except Exception as err:  # noqa: BLE001 - manim optional at build time
        logger.warning(f"manim-inheritance: manim not importable ({err}); skipping")
        return {}
    return {
        name: obj
        for name, obj in vars(manim).items()
        if inspect.isclass(obj) and getattr(obj, "__module__", "").startswith("manim")
    }


# --- DOT generation ---------------------------------------------------------
# Style follows the manim_extensions docs conf.py exactly (ExploreMaths/
# manim_extensions, matching the Manim Community inheritance diagrams):
#   inheritance_graph_attrs = {size: "", splines: spline, concentrate: true,
#                              nodesep: 0.15, ranksep: 0.3}
#   inheritance_node_attrs = {penwidth: 0, shape: box, width/height/margin: 0.05}
#   inheritance_edge_attrs = {penwidth: 1}
# plus its node coloring: manim classes fill #EBF5FB / font #1A5276.
# size="" keeps the SVG scale-free (proportional scaling via CSS). rankdir=LR
# is ours: the full 256-class tree is tall but narrow, so it fits the content
# column; TB would be ~8200pt wide and unreadable at any scale. bgcolor stays
# transparent so the diagram works in dark mode.
DOT_GRAPH_ATTRS = (
    'rankdir=LR, bgcolor="transparent", splines=spline, concentrate=true, '
    'size="", nodesep="0.15", ranksep="0.3"'
)
DOT_NODE_ATTRS = (
    'shape=box, style="filled", penwidth=0, width=0.05, height=0.05, '
    'margin=0.05, fillcolor="#EBF5FB", fontcolor="#1A5276"'
)
DOT_EDGE_ATTRS = 'penwidth=1'

OLD_LINK_RE = re.compile(r"^/ch/([a-z0-9]+)/([a-z0-9-]+)#(.+)$")


def _normalize_link(link: str) -> str:
    m = OLD_LINK_RE.match(link)
    if m:
        part, sec, anchor = m.groups()
        return f"/chapters/{part}/{sec}.html#{anchor.lower()}"
    return link


def _inheritance_edges(classes: dict[str, type]) -> set[tuple[str, str]]:
    """Child -> parent edges; private/missing bases collapse to the nearest
    documented ancestor so every node stays connected."""
    names = set(classes)
    edges: set[tuple[str, str]] = set()
    for name, obj in classes.items():
        direct = [
            b.__name__ for b in obj.__bases__
            if b.__name__ in names and b.__name__ != name
        ]
        if direct:
            edges.update((name, base) for base in direct)
        else:
            for anc in inspect.getmro(obj)[1:]:
                if anc.__name__ in names and anc.__name__ != name:
                    edges.add((name, anc.__name__))
                    break
    return edges


def build_inheritance_dot(
    classes: dict[str, type],
    chapter_links: dict[str, str],
    api_links: dict[str, str],
) -> str:
    lines = [
        "digraph G {",
        f"  graph [{DOT_GRAPH_ATTRS}];",
        f"  node  [{DOT_NODE_ATTRS}];",
        f"  edge  [{DOT_EDGE_ATTRS}];",
    ]
    for name in sorted(classes):
        label = name if len(name) <= 22 else name[:21] + "…"
        link = chapter_links.get(name) or api_links.get(name) or ""
        url = f', URL="{link}"' if link else ""
        lines.append(f'  "{name}" [label="{label}"{url}];')
    for child, parent in sorted(_inheritance_edges(classes)):
        lines.append(f'  "{child}" -> "{parent}";')
    lines.append("}")
    return "\n".join(lines)


# --- directive ---------------------------------------------------------------
class ManimInheritanceDirective(Directive):
    """```{manim-inheritance}

    Full inheritance graph of every public manim class, auto-generated.
    ```
    """

    has_content = False

    def run(self):
        env = self.state.document.settings.env
        classes = load_manim_classes()
        if not classes:
            return []

        chapter_links: dict[str, str] = {}
        links_path = Path(env.config.manim_inheritance_links)
        if links_path.is_file():
            data = json.loads(links_path.read_text(encoding="utf-8"))
            for node in data.get("nodes", []):
                if node.get("name") and node.get("link"):
                    chapter_links[node["name"]] = _normalize_link(node["link"])
        else:
            logger.warning(f"manim-inheritance: links file missing: {links_path}")

        api_links: dict[str, str] = {}
        map_path = Path(env.config.manim_inheritance_api_map)
        if map_path.is_file():
            api_links = json.loads(map_path.read_text(encoding="utf-8"))

        dot = build_inheritance_dot(classes, chapter_links, api_links)
        node = inheritance_graph("")
        node["code"] = dot
        node.source, node.line = self.state.document.current_source, self.lineno
        return [node]


class ManimChainDirective(Directive):
    """```{manimchain}
    digraph G { ... }
    ```

    A small hand-written DOT diagram (e.g. a single class's inheritance
    chain), rendered exactly like the full inheritance graph: inline SVG
    in the official Manim diagram style, clickable node links, no <object>
    frame (so no double border and links navigate the whole page).
    """

    has_content = True

    def run(self):
        node = inheritance_graph("")
        node["code"] = "\n".join(self.content)
        node.source, node.line = self.state.document.current_source, self.lineno
        return [node]


# --- inline SVG rendering -----------------------------------------------------
# The graph carries clickable node links. sphinx.ext.graphviz embeds SVG
# via <object>, where anchors navigate *inside the object frame* (the
# diagram gets replaced by the target page) — useless for jumping to a
# doc section. Rendering the SVG inline makes anchors behave like normal
# page links, and absolute URLs then need no relative-path rewriting.
class inheritance_graph(nodes.General, nodes.Element):
    pass


def _render_inline_svg(code: str) -> str:
    try:
        proc = subprocess.run(
            ["dot", "-Tsvg"], input=code.encode("utf-8"),
            capture_output=True, timeout=120,
        )
    except FileNotFoundError as err:
        raise SphinxError(
            "graphviz 'dot' executable not found; install graphviz to render "
            "the inheritance graph"
        ) from err
    if proc.returncode != 0:
        raise SphinxError(f"dot failed on inheritance graph:\n{proc.stderr.decode('utf-8', 'replace')}")
    svg = proc.stdout.decode("utf-8")
    # drop the XML prolog / doctype / generator comments: inline SVG must
    # start at the <svg> element.
    start = svg.find("<svg")
    if start == -1:
        raise SphinxError("dot produced no <svg> output for the inheritance graph")
    return svg[start:]


def visit_inheritance_graph_html(self, node):
    svg = _render_inline_svg(node["code"])
    self.body.append(
        '<div class="graphviz manim-inheritance">' + svg + "</div>"
    )
    raise nodes.SkipNode


def skip_inheritance_graph(self, node):
    raise nodes.SkipNode


def setup(app):
    app.add_config_value("manim_inheritance_links", "inheritance.json", "env")
    app.add_config_value("manim_inheritance_api_map", "_api_map.json", "env")
    app.add_directive("manim-inheritance", ManimInheritanceDirective)
    app.add_directive("manimchain", ManimChainDirective)
    app.add_node(
        inheritance_graph,
        html=(visit_inheritance_graph_html, None),
        latex=(skip_inheritance_graph, None),
        text=(skip_inheritance_graph, None),
        man=(skip_inheritance_graph, None),
    )
    return {"version": "1.0", "parallel_read_safe": False}
